/** Small interpolation helpers shared by the panel. */

function fill(template, vars) {
  if (typeof template !== 'string') return '';
  return template.replace(/\{(\w+)\}/g, (match, key) => {
    if (!vars || vars[key] === undefined || vars[key] === null) return match;
    return String(vars[key]);
  });
}

function tr(t, key, vars) {
  try {
    return fill(t(key), vars);
  } catch (error) {
    return key;
  }
}

function makeFallbackT(dict) {
  const source = dict || {};
  return (key) => (source[key] === undefined ? key : source[key]);
}

/* Real recorded samples (OLPC Berklee Sound Library, CC BY 3.0). */

const sampleBuffers = new Map();
const samplePending = new Map();

function base64ToBytes(base64) {
  const binary = window.atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function decodeSample(dataUri) {
  const marker = 'data:audio/mpeg;base64,';
  const base64 = dataUri.startsWith(marker) ? dataUri.slice(marker.length) : dataUri.split(',')[1];
  return base64ToBytes(base64);
}

async function fetchSampleBytes(source) {
  if (source.startsWith('data:')) return decodeSample(source);
  const response = await fetch(source);
  if (!response.ok) throw new Error('sample fetch failed: ' + response.status);
  return new Uint8Array(await response.arrayBuffer());
}

async function loadSampleBuffer(key) {
  if (sampleBuffers.has(key)) return sampleBuffers.get(key);
  if (samplePending.has(key)) return samplePending.get(key);
  const data = SAMPLE_AUDIO[key];
  if (!data) return null;
  const context = audioContext();
  if (!context) return null;
  const pending = fetchSampleBytes(data)
    .then((bytes) => context.decodeAudioData(bytes.buffer))
    .then((buffer) => {
      sampleBuffers.set(key, buffer);
      samplePending.delete(key);
      return buffer;
    })
    .catch(() => {
      samplePending.delete(key);
      return null;
    });
  samplePending.set(key, pending);
  return pending;
}

async function preloadSamples(keys) {
  const list = Array.from(new Set(keys)).filter((key) => SAMPLE_AUDIO[key]);
  await Promise.all(list.map((key) => loadSampleBuffer(key)));
  return sampleBuffers;
}

/** Decode every bundled sample while the first user gesture is still running. */
function preloadAllSamples() {
  return preloadSamples(Object.keys(SAMPLE_AUDIO));
}

function playSample(key, options) {
  const settings = options || {};
  const buffer = sampleBuffers.get(key);
  const context = audioContext();
  if (!buffer || !context) return null;
  try {
    if (context.state === 'suspended') context.resume();
    const source = context.createBufferSource();
    source.buffer = buffer;
    const at = context.currentTime + Math.max(0, settings.at || 0);
    const startRate = Math.max(0.25, Math.min(4, settings.rate || 1));
    source.playbackRate.setValueAtTime(startRate, at);
    if (settings.loop) {
      source.loop = true;
      source.loopStart = 0;
      source.loopEnd = buffer.duration;
    }
    const duration = settings.dur
      ? settings.loop
        ? settings.dur
        : Math.min(settings.dur, buffer.duration)
      : undefined;
    if (settings.rateEnd) {
      const endRate = Math.max(0.25, Math.min(4, settings.rateEnd));
      source.playbackRate.exponentialRampToValueAtTime(
        endRate,
        at + (duration || buffer.duration)
      );
    }
    const gain = context.createGain();
    const peak = Math.max(0.0001, settings.gain === undefined ? 0.5 : settings.gain);
    const attack = settings.attack === undefined ? 0.008 : settings.attack;
    const release = settings.release === undefined ? 0.08 : settings.release;
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(peak, at + Math.max(0.004, attack));
    if (duration) {
      gain.gain.setValueAtTime(peak, at + Math.max(attack, duration - release));
      gain.gain.exponentialRampToValueAtTime(0.0001, at + duration);
    }
    let tail = gain;
    if (settings.lowpass) {
      const filter = context.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = Math.max(120, settings.lowpass);
      tail.connect(filter);
      tail = filter;
    }
    if (settings.pan) {
      const panner = context.createStereoPanner();
      panner.pan.value = Math.max(-1, Math.min(1, settings.pan));
      tail.connect(panner);
      panner.connect(context.destination);
      tail = panner;
    } else {
      tail.connect(context.destination);
    }
    source.connect(gain);
    source.start(at, 0);
    if (duration) source.stop(at + duration + 0.05);
    return {
      stop() {
        try {
          source.stop();
        } catch (error) {
          /* already stopped */
        }
        try {
          source.disconnect();
          gain.disconnect();
          if (tail !== gain) tail.disconnect();
        } catch (error) {
          /* already disconnected */
        }
      }
    };
  } catch (error) {
    return null;
  }
}

/**
 * Pure logic for the daily tarot plugin: drawing, topic detection, verdict
 * scoring, reading composition and storage sanitising. No DOM, no globals.
 */

const STORAGE_KEY = 'dsh.tarot.v1';
const POSITIONS = ['past', 'present', 'future'];
const POSITION_ZH = { past: '过去', present: '现在', future: '未来' };
const TIERS = ['yes', 'leanYes', 'mixed', 'no'];
const LIMITS = { keepDays: 30, keepCount: 60 };

const FORTUNE_WEIGHT = { good: 2, neutral: 0, shadow: -2 };
const DAY_MS = 24 * 60 * 60 * 1000;

function pad2(value) {
  return value < 10 ? '0' + value : String(value);
}

/** Local calendar day, e.g. 2026-11-08. */
function dateKey(date) {
  return date.getFullYear() + '-' + pad2(date.getMonth() + 1) + '-' + pad2(date.getDate());
}

/** Trim, collapse control characters and cap the character count. */
function trimText(raw, max) {
  const cleaned = String(raw === undefined || raw === null ? '' : raw)
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const chars = Array.from(cleaned);
  return chars.length > max ? chars.slice(0, max).join('') : cleaned;
}

function shuffle(deck, rng) {
  const pool = deck.slice();
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    const swap = pool[i];
    pool[i] = pool[j];
    pool[j] = swap;
  }
  return pool;
}

/** Draw three unique cards; each orientation is an independent coin flip. */
function drawCards(deck, rng = Math.random) {
  if (!Array.isArray(deck) || deck.length < 3) {
    throw new Error('daily-tarot: deck needs at least three cards');
  }
  return shuffle(deck, rng)
    .slice(0, 3)
    .map((card) => ({ cardId: card.id, reversed: rng() < 0.5 }));
}

function signature(cards) {
  return cards
    .map((slot) => slot.cardId + (slot.reversed ? 'r' : 'u'))
    .sort()
    .join('|');
}

/** Like drawCards, but avoids repeating the previous spread verbatim. */
function pickDistinct(deck, previous, rng = Math.random) {
  let cards = drawCards(deck, rng);
  if (!Array.isArray(previous) || previous.length !== 3) return cards;
  const prev = signature(previous);
  for (let attempt = 0; attempt < 8 && signature(cards) === prev; attempt += 1) {
    cards = drawCards(deck, rng);
  }
  return cards;
}

function newId() {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID();
    }
  } catch (error) {
    /* fall through */
  }
  return 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
}

/** Build a persistable draw record from raw form values. */
function makeDraw(input) {
  const now = input.now === undefined || input.now === null ? Date.now() : Number(input.now);
  return {
    id: input.id || newId(),
    at: now,
    dateKey: dateKey(new Date(now)),
    querent: trimText(input.querent, 24),
    question: trimText(input.question, 60),
    topic: input.topic || 'general',
    cards: (input.cards || []).map((slot) => ({ cardId: slot.cardId, reversed: !!slot.reversed }))
  };
}

/** First topic whose detect keyword appears in the question, else general. */
function detectTopic(question, topics) {
  const text = String(question === undefined || question === null ? '' : question).toLowerCase();
  if (!text.trim()) return 'general';
  for (const topic of topics || []) {
    if (!topic || topic.id === 'general' || !Array.isArray(topic.detect)) continue;
    for (const keyword of topic.detect) {
      const needle = String(keyword === undefined || keyword === null ? '' : keyword).toLowerCase();
      if (needle && text.includes(needle)) return topic.id;
    }
  }
  return 'general';
}

/** Score a spread: good +2, neutral 0, shadow -2. */
function scoreReading(cards, deckById) {
  const entries = (cards || []).map((slot, index) => {
    const card = deckById.get(slot.cardId) || null;
    const orientation = slot.reversed ? 'reversed' : 'upright';
    const fortune = card && card.fortune ? card.fortune[orientation] : 'neutral';
    return {
      index,
      card,
      orientation,
      fortune,
      weight: Object.prototype.hasOwnProperty.call(FORTUNE_WEIGHT, fortune) ? FORTUNE_WEIGHT[fortune] : 0
    };
  });
  const score = entries.reduce((sum, entry) => sum + entry.weight, 0);
  const tier = score >= 4 ? 'yes' : score === 2 ? 'leanYes' : score === 0 ? 'mixed' : 'no';
  let support = 0;
  let challenge = Math.max(0, entries.length - 1);
  entries.forEach((entry, index) => {
    if (entry.weight > entries[support].weight) support = index;
    if (entry.weight < entries[challenge].weight) challenge = index;
  });
  return { entries, score, tier, support: entries[support] || null, challenge: entries[challenge] || null };
}

function hashString(value) {
  let hash = 5381;
  const text = String(value || '');
  for (let i = 0; i < text.length; i += 1) {
    hash = ((hash << 5) + hash + text.charCodeAt(i)) >>> 0;
  }
  return hash;
}

/** Deterministically pick two distinct actions for a draw id. */
function pickActions(actions, seed) {
  const list = (Array.isArray(actions) ? actions : []).filter(
    (item) => typeof item === 'string' && item.length > 0
  );
  if (list.length <= 2) return list.slice(0, 2);
  const hash = hashString(seed);
  const first = hash % list.length;
  const step = 1 + ((hash >>> 4) % (list.length - 1));
  return [list[first], list[(first + step) % list.length]];
}

function formatTemplate(template, vars) {
  if (typeof template !== 'string') return '';
  return template.replace(/\{(\w+)\}/g, (match, key) => {
    if (vars[key] === undefined || vars[key] === null) return match;
    return String(vars[key]);
  });
}

/** Concrete time window for a reading, derived from the present card. */
function timingFor(card, locale) {
  const en = locale === 'en';
  if (card.arcana === 'major') {
    if (card.number <= 7) return en ? 'within a week' : '一周内';
    if (card.number <= 14) return en ? 'within two weeks' : '两周内';
    return en ? 'within a month' : '一个月内';
  }
  if (card.suit === 'wands') return en ? 'within 3-5 days' : '3 到 5 天内';
  if (card.suit === 'swords') return en ? 'within 7-10 days' : '7 到 10 天内';
  if (card.suit === 'cups') return en ? 'within two weeks' : '两周内';
  return en ? 'within a month' : '一个月内';
}

/**
 * Compose the complete reading for a draw.
 * options: { deckById, topicsById, t, locale }
 */
function buildReading(draw, options) {
  const deckById = options.deckById;
  const topicsById = options.topicsById;
  const t = options.t;
  const locale = options.locale || 'zh';
  const topic = topicsById.get(draw.topic) || topicsById.get('general');
  if (!topic) return null;
  const scored = scoreReading(draw.cards, deckById);
  if (!scored.support || !scored.challenge || scored.entries.some((entry) => !entry.card)) return null;

  const querentLabel = draw.querent || t('someone.self');
  const questionLabel = draw.question || t('question.none');
  const presentCard = scored.entries[1].card;
  const timing = timingFor(presentCard, locale);
  const timingZh = timingFor(presentCard, 'zh');
  const supportKw = (scored.support.card.keywords[scored.support.orientation] || [])[0] || '';
  const challengeKw = (scored.challenge.card.keywords[scored.challenge.orientation] || [])[0] || '';
  const cards = scored.entries.map((entry) => {
    const position = POSITIONS[entry.index];
    const card = entry.card;
    const orientation = entry.orientation;
    const keywords = card.keywords[orientation] || [];
    const frame = topic.frames && topic.frames[position] ? topic.frames[position][orientation] : '';
    const assertion = formatTemplate(frame, {
      card: card.name,
      kw1: keywords[0],
      kw2: keywords[1],
      kw3: keywords[2],
      position: POSITION_ZH[position],
      querent: querentLabel,
      question: questionLabel
    });
    const check = formatTemplate(t('check.' + position), {
      kw: keywords[position === 'future' ? 1 : 0],
      timing
    });
    return {
      position,
      positionLabel: t('position.' + position),
      card,
      reversed: !!draw.cards[entry.index].reversed,
      orientation,
      orientationLabel: t(orientation === 'reversed' ? 'orientation.reversed' : 'orientation.upright'),
      name: locale === 'en' ? card.nameEn : card.name,
      keywords,
      text: card.text[orientation] || '',
      assertion,
      check,
      fortune: entry.fortune,
      foil: entry.fortune === 'good'
    };
  });

  const verdictTemplate = topic.verdicts && topic.verdicts[scored.tier] ? topic.verdicts[scored.tier] : '';
  const paragraph = formatTemplate(verdictTemplate, {
    querent: querentLabel,
    question: questionLabel,
    supportCard: scored.support.card.name,
    challengeCard: scored.challenge.card.name,
    supportKw,
    challengeKw,
    timing: timingZh
  });

  const keywords = [];
  cards.forEach((entry) => {
    entry.keywords.forEach((word) => {
      if (keywords.indexOf(word) === -1) keywords.push(word);
    });
  });

  return {
    cards,
    topic,
    tier: scored.tier,
    score: scored.score,
    support: scored.support.card,
    challenge: scored.challenge.card,
    verdict: { tier: scored.tier, label: t('verdict.' + scored.tier), paragraph, timing: timingZh },
    actions: pickActions(topic.actions ? topic.actions[scored.tier] : [], draw.id),
    keywords: keywords.slice(0, 6),
    querent: querentLabel,
    question: questionLabel,
    rawQuestion: draw.question,
    rawQuerent: draw.querent
  };
}

/** Validate one stored draw; returns null when it cannot be trusted. */
function sanitizeDraw(raw, deckById, topicsById) {
  if (!raw || typeof raw !== 'object') return null;
  if (!Array.isArray(raw.cards) || raw.cards.length !== 3) return null;
  const seen = new Set();
  const cards = [];
  for (const slot of raw.cards) {
    if (!slot || typeof slot !== 'object') return null;
    const card = deckById.get(slot.cardId);
    if (!card || seen.has(card.id)) return null;
    seen.add(card.id);
    cards.push({ cardId: card.id, reversed: !!slot.reversed });
  }
  const at = Number(raw.at);
  if (!Number.isFinite(at) || at <= 0) return null;
  const date = new Date(at);
  const storedDate =
    typeof raw.dateKey === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(raw.dateKey)
      ? raw.dateKey
      : dateKey(date);
  const topic =
    typeof raw.topic === 'string' && topicsById.has(raw.topic) ? raw.topic : 'general';
  return {
    id: typeof raw.id === 'string' && raw.id ? raw.id : newId(),
    at,
    dateKey: storedDate,
    querent: trimText(raw.querent, 24),
    question: trimText(raw.question, 60),
    topic,
    cards
  };
}

function pruneDraws(draws, now, limits) {
  const keepDays = (limits && limits.keepDays) || LIMITS.keepDays;
  const keepCount = (limits && limits.keepCount) || LIMITS.keepCount;
  const cutoff = now - keepDays * DAY_MS;
  return (Array.isArray(draws) ? draws : [])
    .filter((draw) => draw && Number.isFinite(draw.at) && draw.at >= cutoff)
    .slice(0, keepCount);
}

/** Drop invalid or duplicate entries and cap the history. */
function sanitizeStore(raw, deckById, topicsById, now = Date.now()) {
  const list = raw && Array.isArray(raw.draws) ? raw.draws : [];
  const draws = [];
  const ids = new Set();
  for (const entry of list) {
    const clean = sanitizeDraw(entry, deckById, topicsById);
    if (!clean || ids.has(clean.id)) continue;
    ids.add(clean.id);
    draws.push(clean);
  }
  draws.sort((a, b) => b.at - a.at);
  return { version: 1, draws: pruneDraws(draws, now) };
}

function appendDraw(draws, draw, now = Date.now()) {
  return pruneDraws([draw, ...draws], now);
}

function loadStore(storage) {
  if (!storage) return { version: 1, draws: [] };
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return { version: 1, draws: [] };
    const parsed = JSON.parse(raw);
    return parsed && Array.isArray(parsed.draws) ? parsed : { version: 1, draws: [] };
  } catch (error) {
    return { version: 1, draws: [] };
  }
}

function saveStore(storage, store) {
  if (!storage) return false;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(store));
    return true;
  } catch (error) {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Fate undercolour (one Major Arcana card)                            */
/* ------------------------------------------------------------------ */

const FATE_KEY = 'dsh.tarot.fate.v1';
const POTION_SHAPES = [
  'orb',
  'flask',
  'vial',
  'conical',
  'teardrop',
  'crescent',
  'heart',
  'skull',
  'star',
  'ampoule'
];

/** Draw exactly one Major Arcana card; orientation is an independent flip. */
function drawFateCard(deck, previous, rng = Math.random) {
  const pool = (Array.isArray(deck) ? deck : []).filter((card) => card && card.arcana === 'major');
  if (!pool.length) throw new Error('daily-tarot: fate deck needs Major Arcana cards');
  const pickOne = () => pool[Math.min(pool.length - 1, Math.floor(rng() * pool.length))];
  let card = pickOne();
  const previousId = previous && previous.cardId;
  for (let attempt = 0; attempt < 8 && previousId && card.id === previousId; attempt += 1) {
    card = pickOne();
  }
  return { cardId: card.id, reversed: rng() < 0.5 };
}

function makeFateDraw(input) {
  const now = input.now === undefined || input.now === null ? Date.now() : Number(input.now);
  return {
    id: input.id || newId(),
    at: now,
    dateKey: dateKey(new Date(now)),
    querent: trimText(input.querent, 24),
    cardId: String(input.cardId || ''),
    reversed: !!input.reversed
  };
}

function sanitizeFateDraw(raw, deckById) {
  if (!raw || typeof raw !== 'object') return null;
  const card = deckById.get(String(raw.cardId || ''));
  if (!card || card.arcana !== 'major') return null;
  const at = Number(raw.at);
  if (!Number.isFinite(at) || at <= 0) return null;
  const date = new Date(at);
  const storedDate =
    typeof raw.dateKey === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(raw.dateKey)
      ? raw.dateKey
      : dateKey(date);
  return {
    id: typeof raw.id === 'string' && raw.id ? raw.id : newId(),
    at,
    dateKey: storedDate,
    querent: trimText(raw.querent, 24),
    cardId: card.id,
    reversed: !!raw.reversed
  };
}

function clampByte(value) {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function parseHex(hex) {
  const text = String(hex || '').trim();
  const match = /^#?([0-9a-fA-F]{6})$/.exec(text);
  if (!match) return { r: 11, g: 9, b: 16 };
  const value = parseInt(match[1], 16);
  return { r: (value >> 16) & 255, g: (value >> 8) & 255, b: value & 255 };
}

function toHex(rgb) {
  const part = (value) => clampByte(value).toString(16).padStart(2, '0');
  return '#' + part(rgb.r) + part(rgb.g) + part(rgb.b);
}

/** Blend two hex colours; t=0 returns a, t=1 returns b. */
function mixHex(a, b, t) {
  const ratio = Math.max(0, Math.min(1, Number(t) || 0));
  const left = parseHex(a);
  const right = parseHex(b);
  return toHex({
    r: left.r + (right.r - left.r) * ratio,
    g: left.g + (right.g - left.g) * ratio,
    b: left.b + (right.b - left.b) * ratio
  });
}

/** Pick near-black or bone-white ink for readable text over a colour. */
function readableInk(hex) {
  const rgb = parseHex(hex);
  const luminance = (0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b) / 255;
  return luminance > 0.58 ? '#0b0910' : '#f7ecd6';
}

/** Stable potion shape and colour for a Major Arcana card. */
function potionFor(card, reversed, fate) {
  const shape =
    POTION_SHAPES[hashString(String(card.id) + (reversed ? 'r' : 'u')) % POTION_SHAPES.length];
  const color = fate && typeof fate.color === 'string' ? fate.color : '#c9a15a';
  const colorName = fate && fate.colorName ? fate.colorName : '';
  return {
    shape,
    color,
    colorName,
    name: colorName ? colorName + '魔药' : '命运魔药'
  };
}

function buildFateReading(draw, options) {
  const deckById = options.deckById;
  const fateById = options.fateById;
  const t = options.t;
  const locale = options.locale || 'zh';
  const card = deckById.get(String(draw.cardId || ''));
  if (!card || card.arcana !== 'major') return null;
  const fate = fateById.get(card.id);
  if (!fate) return null;
  const orientation = draw.reversed ? 'reversed' : 'upright';
  const querent = draw.querent || t('someone.self');
  const vars = { querent, card: card.name };
  const potion = potionFor(card, !!draw.reversed, fate);
  return {
    card,
    reversed: !!draw.reversed,
    orientation,
    orientationLabel: t(orientation === 'reversed' ? 'orientation.reversed' : 'orientation.upright'),
    name: locale === 'en' ? card.nameEn : card.name,
    nameEn: card.nameEn,
    color: potion.color,
    colorName: potion.colorName,
    essence: formatTemplate(fate.essence, vars),
    advice: formatTemplate(fate.advice, vars),
    keywords: (card.keywords[orientation] || []).slice(0, 3),
    text: card.text[orientation] || '',
    potion,
    querent
  };
}

function loadFate(storage) {
  if (!storage) return null;
  try {
    const raw = storage.getItem(FATE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (error) {
    return null;
  }
}

function saveFate(storage, draw) {
  if (!storage) return false;
  try {
    storage.setItem(FATE_KEY, JSON.stringify(draw));
    return true;
  } catch (error) {
    return false;
  }
}

/**
 * Audio for the tarot panel.
 *
 * The charge riser is synthesised, but every signature sting, the witch's
 * laugh and the potion pour use short real recordings (OLPC Berklee Sound
 * Library, CC BY 3.0) decoded through Web Audio.
 */

let sharedContext = null;
let sharedNoise = null;

function audioContext() {
  if (sharedContext) return sharedContext;
  if (typeof window === 'undefined') return null;
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null;
  try {
    sharedContext = new Ctor();
  } catch (error) {
    sharedContext = null;
  }
  return sharedContext;
}

function noiseBuffer(context, seconds) {
  if (sharedNoise && sharedNoise.duration >= seconds && sharedNoise.sampleRate === context.sampleRate) {
    return sharedNoise;
  }
  const length = Math.max(1, Math.ceil(context.sampleRate * seconds));
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const data = buffer.getChannelData(0);
  for (let index = 0; index < length; index += 1) {
    data[index] = Math.random() * 2 - 1;
  }
  sharedNoise = buffer;
  return buffer;
}

/** A rising charge-up riser with air whooshes; stops cleanly when skipped. */
function playCharge(options = {}) {
  const context = audioContext();
  if (!context) return () => {};
  const durationMs = options.durationMs || 2080;
  const landingMs = options.landingMs || 1100;
  const count = options.count || 3;
  try {
    if (context.state === 'suspended') context.resume();
    preloadAllSamples().catch(() => {});
    const start = context.currentTime + 0.04;
    const seconds = durationMs / 1000;
    const master = context.createGain();
    master.gain.setValueAtTime(0.0001, start);
    master.gain.linearRampToValueAtTime(0.24, start + seconds * 0.86);
    master.gain.linearRampToValueAtTime(0.0001, start + seconds);
    master.connect(context.destination);

    const tone = context.createOscillator();
    tone.type = 'sawtooth';
    tone.frequency.setValueAtTime(68, start);
    tone.frequency.exponentialRampToValueAtTime(540, start + seconds * 0.9);
    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(260, start);
    filter.frequency.exponentialRampToValueAtTime(3400, start + seconds * 0.9);
    const toneGain = context.createGain();
    toneGain.gain.value = 0.24;
    tone.connect(filter);
    filter.connect(toneGain);
    toneGain.connect(master);
    tone.start(start);
    tone.stop(start + seconds + 0.02);

    const sub = context.createOscillator();
    sub.type = 'sine';
    sub.frequency.setValueAtTime(42, start);
    sub.frequency.exponentialRampToValueAtTime(74, start + seconds);
    const subGain = context.createGain();
    subGain.gain.value = 0.2;
    sub.connect(subGain);
    subGain.connect(master);
    sub.start(start);
    sub.stop(start + seconds + 0.02);

    const air = context.createBufferSource();
    air.buffer = noiseBuffer(context, seconds);
    const airFilter = context.createBiquadFilter();
    airFilter.type = 'bandpass';
    airFilter.Q.value = 1.1;
    airFilter.frequency.setValueAtTime(320, start);
    airFilter.frequency.exponentialRampToValueAtTime(2600, start + seconds);
    const airGain = context.createGain();
    airGain.gain.setValueAtTime(0.0001, start);
    airGain.gain.linearRampToValueAtTime(0.12, start + seconds * 0.8);
    airGain.gain.linearRampToValueAtTime(0.0001, start + seconds);
    air.connect(airFilter);
    airFilter.connect(airGain);
    airGain.connect(master);
    air.start(start);
    air.stop(start + seconds + 0.02);

    const whooshes = [];
    for (let index = 0; index < Math.max(1, count); index += 1) {
      const whoosh = context.createBufferSource();
      whoosh.buffer = noiseBuffer(context, 0.4);
      const whooshFilter = context.createBiquadFilter();
      whooshFilter.type = 'bandpass';
      whooshFilter.Q.value = 0.9;
      whooshFilter.frequency.setValueAtTime(380, start);
      const whooshGain = context.createGain();
      whooshGain.gain.value = 0;
      whoosh.connect(whooshFilter);
      whooshFilter.connect(whooshGain);
      whooshGain.connect(master);
      const at = start + seconds * (0.6 + index * 0.1);
      whooshFilter.frequency.setValueAtTime(380, at);
      whooshFilter.frequency.exponentialRampToValueAtTime(2200, at + 0.22);
      whooshGain.gain.setValueAtTime(0.0001, at);
      whooshGain.gain.linearRampToValueAtTime(0.22, at + 0.05);
      whooshGain.gain.exponentialRampToValueAtTime(0.0001, at + 0.28);
      whoosh.start(at);
      whoosh.stop(at + 0.34);
      whooshes.push(whoosh);
    }

    const nodes = [tone, sub, air, ...whooshes];
    return function stop() {
      try {
        const now = context.currentTime;
        master.gain.cancelScheduledValues(now);
        master.gain.setTargetAtTime(0.0001, now, 0.04);
      } catch (error) {
        /* already stopped */
      }
      window.setTimeout(() => {
        for (const node of nodes) {
          try {
            node.stop();
          } catch (error) {
            /* already stopped */
          }
        }
        try {
          master.disconnect();
        } catch (error) {
          /* already disconnected */
        }
      }, 240);
    };
  } catch (error) {
    return () => {};
  }
}

/* ------------------------------------------------------------------ */
/* Real sample recipes                                                 */
/* ------------------------------------------------------------------ */

const SAMPLE_ROOT = {
  voice_a3: 57,
  voice_cs4: 61,
  voice_fs5: 78,
  piano_low: 36,
  piano_mid: 51,
  piano_high: 91
};

function rateFor(key, midi) {
  const root = SAMPLE_ROOT[key];
  if (!root) return 1;
  return Math.pow(2, (midi - root) / 12);
}

function voice(at, midi, gain, dur, extra) {
  let key = 'voice_a3';
  if (midi >= 72) key = 'voice_fs5';
  else if (midi >= 64) key = 'voice_cs4';
  return Object.assign({ key, at, gain, dur, rate: rateFor(key, midi) }, extra || {});
}

function piano(at, midi, gain, dur, extra) {
  let key = 'piano_mid';
  if (midi < 45) key = 'piano_low';
  else if (midi > 76) key = 'piano_high';
  return Object.assign({ key, at, gain, dur, rate: rateFor(key, midi) }, extra || {});
}

function chord(at, midis, gain, dur, extra) {
  return midis.map((midi) => voice(at, midi, gain, dur, extra));
}

function fluteNote(at, midi, gain, dur, extra) {
  return Object.assign(
    { key: 'flute', at, gain, dur, rate: Math.pow(2, (midi - 72) / 12) },
    extra || {}
  );
}

function celloNote(at, midi, gain, dur, extra) {
  return Object.assign(
    { key: 'cello', at, gain, dur, rate: Math.pow(2, (midi - 48) / 12), lowpass: 3600 },
    extra || {}
  );
}

function bellNote(at, midi, gain, dur, extra) {
  return Object.assign(
    { key: midi >= 84 ? 'bell_2' : 'bell_1', at, gain, dur, rate: Math.pow(2, (midi - 72) / 12) },
    extra || {}
  );
}

function rumble(at, gain, dur) {
  return {
    key: 'explosion',
    at,
    gain,
    dur,
    rate: 0.32,
    loop: true,
    lowpass: 150,
    attack: 0.8,
    release: 1.2
  };
}

function drone(at, midi, gain, dur, extra) {
  return Object.assign(
    { key: 'voice_a3', at, gain, dur, rate: Math.max(0.25, rateFor('voice_a3', midi)), loop: true, lowpass: 600 },
    extra || {}
  );
}

