/**
 * Build a QR matrix for a short URL. Returns { count, rows, dark(r,c) }.
 * The matrix is rendered by share.js; no DOM is touched here.
 */
function qrMatrix(text, errorCorrectionLevel) {
  const qr = qrcode(0, errorCorrectionLevel || 'M');
  qr.addData(String(text));
  qr.make();
  const count = qr.getModuleCount();
  const rows = [];
  for (let row = 0; row < count; row += 1) {
    let line = '';
    for (let col = 0; col < count; col += 1) line += qr.isDark(row, col) ? '1' : '0';
    rows.push(line);
  }
  return { count, rows, dark: (row, col) => qr.isDark(row, col) };
}

/* Share posters for the reading result (spread and fate). */

const POSTER_W = 1080;
const POSTER_H = 1440;
const POSTER_URL_FALLBACK = 'https://zakchin.github.io/feiyu-tarot/';
const SERIF = '"Songti SC", "Noto Serif SC", "Microsoft YaHei", serif';

function shareUrl() {
  if (typeof SITE_URL === 'string' && SITE_URL) return SITE_URL;
  return POSTER_URL_FALLBACK;
}

function loadArtImage(source) {
  return new Promise((resolve) => {
    if (!source || typeof Image === 'undefined') {
      resolve(null);
      return;
    }
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => resolve(null);
    image.src = source;
  });
}

function drawCover(ctx, image, x, y, width, height) {
  if (!image) {
    ctx.save();
    ctx.fillStyle = '#140d1c';
    ctx.fillRect(x, y, width, height);
    ctx.strokeStyle = 'rgba(201,161,90,.72)';
    ctx.lineWidth = 2;
    ctx.strokeRect(x + 1, y + 1, width - 2, height - 2);
    ctx.restore();
    return;
  }
  const sourceRatio = image.width / image.height;
  const targetRatio = width / height;
  let sx = 0;
  let sy = 0;
  let sw = image.width;
  let sh = image.height;
  if (sourceRatio > targetRatio) {
    sw = image.height * targetRatio;
    sx = (image.width - sw) / 2;
  } else {
    sh = image.width / targetRatio;
    sy = (image.height - sh) / 2;
  }
  ctx.drawImage(image, sx, sy, sw, sh, x, y, width, height);
}

function drawPosterCard(ctx, image, x, y, width, height, reversed) {
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,.7)';
  ctx.shadowBlur = 26;
  ctx.shadowOffsetY = 12;
  ctx.fillStyle = '#0c0811';
  ctx.fillRect(x - 4, y - 4, width + 8, height + 8);
  ctx.restore();
  ctx.save();
  if (reversed) {
    ctx.translate(x + width / 2, y + height / 2);
    ctx.rotate(Math.PI);
    drawCover(ctx, image, -width / 2, -height / 2, width, height);
  } else {
    drawCover(ctx, image, x, y, width, height);
  }
  ctx.restore();
  ctx.save();
  ctx.strokeStyle = 'rgba(201,161,90,.8)';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, width - 2, height - 2);
  ctx.restore();
}

function wrapLines(ctx, text, maxWidth, maxLines) {
  const source = String(text || '').replace(/\s+/g, ' ').trim();
  if (!source) return [];
  const lines = [];
  let current = '';
  for (const char of Array.from(source)) {
    const next = current + char;
    if (ctx.measureText(next).width > maxWidth && current) {
      lines.push(current);
      current = char;
      if (lines.length >= maxLines) break;
    } else {
      current = next;
    }
  }
  if (lines.length < maxLines && current) lines.push(current);
  if (lines.length >= maxLines) {
    const last = lines[maxLines - 1];
    if (last && ctx.measureText(last + '…').width <= maxWidth) {
      lines[maxLines - 1] = last + '…';
    } else if (last) {
      lines[maxLines - 1] = last.slice(0, Math.max(1, last.length - 1)) + '…';
    }
  }
  return lines;
}

function drawLines(ctx, lines, x, y, lineHeight) {
  lines.forEach((line, index) => {
    ctx.fillText(line, x, y + index * lineHeight);
  });
  return y + lines.length * lineHeight;
}

function paintPosterBase(ctx, seed) {
  const background = ctx.createLinearGradient(0, 0, 0, POSTER_H);
  background.addColorStop(0, '#07050c');
  background.addColorStop(0.55, '#121022');
  background.addColorStop(1, '#08050d');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, POSTER_W, POSTER_H);
  const glow = ctx.createRadialGradient(780, 250, 20, 780, 250, 620);
  glow.addColorStop(0, 'rgba(201,161,90,.24)');
  glow.addColorStop(1, 'rgba(201,161,90,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, POSTER_W, POSTER_H);
  for (let index = 0; index < 120; index += 1) {
    const x = (index * 137.5 + seed * 19) % POSTER_W;
    const y = (index * 211.7 + seed * 37) % POSTER_H;
    const size = index % 11 === 0 ? 2.4 : 1.1;
    ctx.fillStyle = index % 5 === 0 ? 'rgba(201,161,90,.75)' : 'rgba(232,220,200,.45)';
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(201,161,90,.72)';
  ctx.lineWidth = 2;
  ctx.strokeRect(28, 28, POSTER_W - 56, POSTER_H - 56);
  ctx.strokeStyle = 'rgba(125,34,51,.55)';
  ctx.lineWidth = 1;
  ctx.strokeRect(40, 40, POSTER_W - 80, POSTER_H - 80);
}

function paintBrand(ctx, t, dateLabel) {
  ctx.textAlign = 'left';
  ctx.fillStyle = '#e8dcc8';
  ctx.font = '600 54px ' + SERIF;
  ctx.fillText(t('share.posterKicker'), 68, 108);
  ctx.fillStyle = '#c9a15a';
  ctx.font = '500 22px ' + SERIF;
  ctx.fillText('FEIYU TAROT', 70, 146);
  if (dateLabel) {
    ctx.fillStyle = 'rgba(201,177,140,.9)';
    ctx.font = '400 20px ' + SERIF;
    ctx.fillText(dateLabel, 70, 180);
  }
}

function drawQr(ctx, text, x, y, size) {
  const matrix = qrMatrix(text, 'M');
  const quiet = 4;
  const cell = size / (matrix.count + quiet * 2);
  const pad = cell * quiet;
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = '#f7efdd';
  ctx.fillRect(x - pad, y - pad, size + pad * 2, size + pad * 2);
  ctx.strokeStyle = 'rgba(201,161,90,.85)';
  ctx.lineWidth = 2;
  ctx.strokeRect(x - pad, y - pad, size + pad * 2, size + pad * 2);
  ctx.fillStyle = '#0b0910';
  for (let row = 0; row < matrix.count; row += 1) {
    for (let col = 0; col < matrix.count; col += 1) {
      if (!matrix.dark(row, col)) continue;
      ctx.fillRect(x + col * cell, y + row * cell, Math.ceil(cell), Math.ceil(cell));
    }
  }
  ctx.restore();
}

function paintFooter(ctx, t, siteUrl) {
  drawQr(ctx, siteUrl, 830, 62, 160);
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(201,161,90,.9)';
  ctx.font = '400 22px ' + SERIF;
  ctx.fillText(t('share.scan'), POSTER_W / 2, 1352);
  ctx.fillStyle = 'rgba(155,140,116,.85)';
  ctx.font = '400 18px ' + SERIF;
  ctx.fillText(siteUrl.replace(/^https?:\/\//, '').replace(/\/$/, ''), POSTER_W / 2, 1384);
}

async function buildSpreadPoster({ draw, reading, t, siteUrl }) {
  const canvas = document.createElement('canvas');
  canvas.width = POSTER_W;
  canvas.height = POSTER_H;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('canvas 2d is unavailable');
  const seed = Array.from(String(draw && draw.id ? draw.id : 'poster')).reduce(
    (sum, char) => (sum + char.charCodeAt(0)) % 97,
    0
  );
  paintPosterBase(ctx, seed);
  paintBrand(ctx, t, (draw && draw.dateKey) || '');
  const entries = (reading && reading.cards) || [];
  const images = await Promise.all(entries.map((entry) => loadArtImage(CARD_ART[entry.card.id])));
  const cardWidth = 292;
  const cardHeight = 408;
  const gap = 32;
  const total = entries.length * cardWidth + Math.max(0, entries.length - 1) * gap;
  const startX = (POSTER_W - total) / 2;
  entries.forEach((entry, index) => {
    const x = startX + index * (cardWidth + gap);
    drawPosterCard(ctx, images[index], x, 250, cardWidth, cardHeight, entry.reversed);
    ctx.textAlign = 'center';
    ctx.fillStyle = '#e8dcc8';
    ctx.font = '500 24px ' + SERIF;
    ctx.fillText(entry.name, x + cardWidth / 2, 672);
    ctx.fillStyle = entry.reversed ? '#d8a35f' : 'rgba(201,177,140,.85)';
    ctx.font = '400 18px ' + SERIF;
    ctx.fillText(entry.positionLabel + ' · ' + entry.orientationLabel, x + cardWidth / 2, 704);
  });
  ctx.textAlign = 'left';
  ctx.fillStyle = '#c9a15a';
  ctx.font = '500 20px ' + SERIF;
  ctx.fillText(t('share.posterQuestion'), 68, 772);
  ctx.fillStyle = '#ece2cc';
  ctx.font = '400 30px ' + SERIF;
  const questionLines = wrapLines(ctx, (draw && draw.question) || '', POSTER_W - 136, 3);
  let cursor = drawLines(ctx, questionLines, 68, 816, 42) + 20;
  ctx.strokeStyle = 'rgba(201,161,90,.34)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(68, cursor);
  ctx.lineTo(POSTER_W - 68, cursor);
  ctx.stroke();
  cursor += 56;
  if (reading && reading.verdict) {
    ctx.fillStyle = '#c9a15a';
    ctx.font = '600 36px ' + SERIF;
    ctx.fillText(reading.verdict.label, 68, cursor);
    cursor += 42;
    if (reading.verdict.timing) {
      ctx.fillStyle = 'rgba(201,177,140,.9)';
      ctx.font = '400 22px ' + SERIF;
      ctx.fillText(t('verdict.timing') + ' · ' + reading.verdict.timing, 70, cursor);
      cursor += 38;
    }
    ctx.fillStyle = 'rgba(236,226,204,.92)';
    ctx.font = '400 25px ' + SERIF;
    const maxLines = Math.max(2, Math.min(7, Math.floor((1320 - cursor) / 40)));
    const lines = wrapLines(ctx, reading.verdict.paragraph, POSTER_W - 136, maxLines);
    drawLines(ctx, lines, 68, cursor, 40);
  }
  paintFooter(ctx, t, siteUrl || shareUrl());
  return canvas;
}

async function buildFatePoster({ draw, reading, t, siteUrl }) {
  const canvas = document.createElement('canvas');
  canvas.width = POSTER_W;
  canvas.height = POSTER_H;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('canvas 2d is unavailable');
  const seed = Array.from(String(draw && draw.id ? draw.id : 'fate')).reduce(
    (sum, char) => (sum + char.charCodeAt(0)) % 97,
    0
  );
  paintPosterBase(ctx, seed);
  paintBrand(ctx, t, (draw && draw.dateKey) || '');
  const tint = mixHex((reading && reading.color) || '#c9a15a', '#0b0910', 0.66);
  const wash = ctx.createRadialGradient(760, 520, 20, 760, 520, 520);
  wash.addColorStop(0, tint);
  wash.addColorStop(1, 'rgba(7,5,12,0)');
  ctx.fillStyle = wash;
  ctx.fillRect(0, 150, POSTER_W, 900);
  const image = await loadArtImage(CARD_ART[reading.card.id]);
  drawPosterCard(ctx, image, 620, 250, 340, 474, reading.reversed);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#c9a15a';
  ctx.font = '500 20px ' + SERIF;
  ctx.fillText(t('fate.resultKicker'), 68, 276);
  ctx.fillStyle = '#ece2cc';
  ctx.font = '600 50px ' + SERIF;
  ctx.fillText(reading.name, 68, 340);
  ctx.fillStyle = '#c9a15a';
  ctx.font = '400 24px ' + SERIF;
  ctx.fillText(reading.orientationLabel + ' · ' + t('fate.color') + ' ' + reading.colorName, 70, 380);
  ctx.fillStyle = reading.color || '#c9a15a';
  ctx.beginPath();
  ctx.arc(100, 470, 34, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(232,220,200,.6)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = 'rgba(236,226,204,.94)';
  ctx.font = '400 26px ' + SERIF;
  const essenceLines = wrapLines(ctx, reading.essence, POSTER_W - 520, 8);
  let cursor = drawLines(ctx, essenceLines, 68, 540, 44) + 26;
  ctx.fillStyle = 'rgba(201,161,90,.95)';
  ctx.font = '500 22px ' + SERIF;
  ctx.fillText(t('potion.kicker'), 68, cursor);
  cursor += 40;
  ctx.fillStyle = 'rgba(236,226,204,.88)';
  ctx.font = '400 24px ' + SERIF;
  const adviceLines = wrapLines(ctx, reading.advice, POSTER_W - 136, 8);
  drawLines(ctx, adviceLines, 68, cursor, 40);
  paintFooter(ctx, t, siteUrl || shareUrl());
  return canvas;
}

/**
 * Client view for the daily tarot panel: gothic card art, the spread, the
 * reading (per-card assertions + verdict) and the local history.
 */

const DECK_BY_ID = new Map(CARDS.map((card) => [card.id, card]));
