function getStorage() {
  try {
    return typeof window !== 'undefined' ? window.localStorage : null;
  } catch (error) {
    return null;
  }
}

function probeStorage(storage) {
  if (!storage) return false;
  try {
    const key = 'dsh.tarot.probe';
    storage.setItem(key, '1');
    storage.removeItem(key);
    return true;
  } catch (error) {
    return false;
  }
}

function prefersReduced() {
  try {
    return (
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
    );
  } catch (error) {
    return false;
  }
}

function parseDay(key) {
  const parts = String(key).split('-').map((part) => Number(part));
  return new Date(parts[0], (parts[1] || 1) - 1, parts[2] || 1);
}

function formatFullDate(key, localeId) {
  try {
    const formatter = new Intl.DateTimeFormat(localeId === 'en' ? 'en-US' : 'zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long'
    });
    return formatter.format(parseDay(key));
  } catch (error) {
    return key;
  }
}

function formatDate(key, localeId) {
  try {
    const formatter = new Intl.DateTimeFormat(localeId === 'en' ? 'en-US' : 'zh-CN', {
      month: 'short',
      day: 'numeric',
      weekday: 'short'
    });
    return formatter.format(parseDay(key));
  } catch (error) {
    return key;
  }
}

function formatTime(ts, localeId) {
  try {
    const formatter = new Intl.DateTimeFormat(localeId === 'en' ? 'en-US' : 'zh-CN', {
      hour: '2-digit',
      minute: '2-digit'
    });
    return formatter.format(new Date(ts));
  } catch (error) {
    return '';
  }
}

function cardName(card, localeId) {
  return localeId === 'en' ? card.nameEn : card.name;
}

function toRoman(number) {
  if (number === 0) return '0';
  const table = [
    [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
  ];
  let rest = number;
  let out = '';
  for (const entry of table) {
    while (rest >= entry[0]) {
      out += entry[1];
      rest -= entry[0];
    }
  }
  return out;
}

function rankLabel(rank) {
  if (rank === 1) return 'A';
  if (rank === 11) return 'P';
  if (rank === 12) return 'Kn';
  if (rank === 13) return 'Q';
  if (rank === 14) return 'K';
  return String(rank);
}

