const MODE_TABS = [
  { id: 'spread', labelKey: 'tab.spread' },
  { id: 'fate', labelKey: 'tab.fate' },
  { id: 'library', labelKey: 'tab.library' }
];

const LIBRARY_FILTERS = [
  { id: 'all', labelKey: 'library.filter.all' },
  { id: 'major', labelKey: 'library.filter.major' },
  { id: 'wands', labelKey: 'library.filter.wands' },
  { id: 'cups', labelKey: 'library.filter.cups' },
  { id: 'swords', labelKey: 'library.filter.swords' },
  { id: 'pentacles', labelKey: 'library.filter.pentacles' }
];

function mergeStops(stops) {
  const list = (Array.isArray(stops) ? stops : [stops]).filter(
    (stop) => typeof stop === 'function'
  );
  return function stopAll() {
    list.forEach((stop) => {
      try {
        stop();
      } catch (error) {
        /* audio is best effort */
      }
    });
  };
}

function matchesLibraryFilter(card, filter) {
  if (!card) return false;
  if (filter === 'all') return true;
  if (filter === 'major') return card.arcana === 'major';
  return card.arcana === 'minor' && card.suit === filter;
}

function cardTypeLabel(card, t) {
  if (card.arcana === 'major') return t('library.type.major') + ' · ' + toRoman(card.number);
  return t('library.type.' + card.suit) + ' · ' + rankLabel(card.rank);
}

