function FateAltar() {
  const ticks = [];
  for (let index = 0; index < 24; index += 1) {
    const angle = (index / 24) * Math.PI * 2;
    const long = index % 3 === 0;
    const inner = long ? 138 : 148;
    ticks.push(
      h('line', {
        key: 'tick-' + index,
        x1: 200 + Math.cos(angle) * inner,
        y1: 200 + Math.sin(angle) * inner,
        x2: 200 + Math.cos(angle) * 158,
        y2: 200 + Math.sin(angle) * 158,
        stroke: '#c9a15a',
        strokeWidth: long ? 1.4 : 0.7,
        opacity: long ? 0.5 : 0.3
      })
    );
  }
  return h(
    'svg',
    { className: 'dsh-tarot-fate-altar', viewBox: '0 0 400 400', 'aria-hidden': 'true' },
    h('circle', { cx: 200, cy: 200, r: 176, fill: 'none', stroke: '#c9a15a', strokeOpacity: 0.2 }),
    h('circle', {
      cx: 200,
      cy: 200,
      r: 166,
      fill: 'none',
      stroke: '#c9a15a',
      strokeOpacity: 0.4,
      strokeDasharray: '1 5'
    }),
    h('circle', { cx: 200, cy: 200, r: 120, fill: 'none', stroke: '#8b6bb5', strokeOpacity: 0.3 }),
    h('circle', {
      cx: 200,
      cy: 200,
      r: 96,
      fill: 'none',
      stroke: '#b03a4a',
      strokeOpacity: 0.3,
      strokeDasharray: '6 4'
    }),
    h('ellipse', {
      cx: 200,
      cy: 200,
      rx: 176,
      ry: 62,
      fill: 'none',
      stroke: '#c9a15a',
      strokeOpacity: 0.22,
      transform: 'rotate(-18 200 200)'
    }),
    ticks,
    [[200, 46], [334, 128], [318, 300], [86, 286], [62, 120]].map(([cx, cy], index) =>
      h('path', {
        key: 'altar-star-' + index,
        d: 'M' + cx + ' ' + (cy - 6) + ' L' + (cx + 2) + ' ' + (cy - 2) + ' L' + (cx + 6) + ' ' + cy + ' L' + (cx + 2) + ' ' + (cy + 2) + ' L' + cx + ' ' + (cy + 6) + ' L' + (cx - 2) + ' ' + (cy + 2) + ' L' + (cx - 6) + ' ' + cy + ' L' + (cx - 2) + ' ' + (cy - 2) + ' Z',
        fill: index % 2 ? '#c9a15a' : '#8b6bb5',
        opacity: 0.7
      })
    )
  );
}

