function PosterOverlay({ src, t, onClose }) {
  React.useEffect(() => {
    function onKey(event) {
      if (event.key === 'Escape') onClose();
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);
  return h(
    'div',
    {
      className: 'dsh-tarot-poster-layer',
      role: 'dialog',
      'aria-modal': 'true',
      'aria-label': t('share.poster'),
      onClick: onClose
    },
    h(
      'div',
      { className: 'dsh-tarot-poster-card', onClick: (event) => event.stopPropagation() },
      h('img', { src, alt: t('share.poster'), draggable: false }),
      h('p', { className: 'dsh-tarot-poster-hint' }, t('share.hint')),
      h(
        'div',
        { className: 'dsh-tarot-poster-actions' },
        h(
          'a',
          { className: 'dsh-tarot-ghost', href: src, download: 'feiyu-tarot.png' },
          t('share.download')
        ),
        h('button', { type: 'button', className: 'dsh-tarot-primary', onClick: onClose }, t('share.close'))
      )
    )
  );
}

function CardViewer({ card, t, localeId, index, total, onClose, onPrev, onNext, inline }) {
  const [rx, setRx] = React.useState(-8);
  const [ry, setRy] = React.useState(0);
  const [zoom, setZoom] = React.useState(1);
  const [auto, setAuto] = React.useState(false);
  const [reversed, setReversed] = React.useState(false);
  const dragRef = React.useRef(null);
  const rootRef = React.useRef(null);

  React.useEffect(() => {
    setRx(-8);
    setRy(0);
    setZoom(1);
    setReversed(false);
  }, [card.id]);

  React.useEffect(() => {
    if (!inline) return undefined;
    const frame = window.requestAnimationFrame(() => {
      const node = rootRef.current;
      if (!node || typeof node.scrollIntoView !== 'function') return;
      try {
        node.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      } catch (error) {
        node.scrollIntoView();
      }
    });
    return () => window.cancelAnimationFrame(frame);
  }, [inline, card.id]);

  React.useEffect(() => {
    if (!auto) return undefined;
    const timer = window.setInterval(() => setRy((value) => value + 0.7), 40);
    return () => window.clearInterval(timer);
  }, [auto]);

  React.useEffect(() => {
    function onKey(event) {
      if (event.key === 'Escape') onClose();
      else if (event.key === 'ArrowLeft') onPrev();
      else if (event.key === 'ArrowRight') onNext();
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose, onPrev, onNext]);

  function reset() {
    setRx(-8);
    setRy(0);
    setZoom(1);
  }

  function onPointerDown(event) {
    if (event.button !== undefined && event.button !== 0) return;
    dragRef.current = { x: event.clientX, y: event.clientY, rx, ry };
    setAuto(false);
    try {
      event.currentTarget.setPointerCapture(event.pointerId);
    } catch (error) {
      /* capture is optional */
    }
  }

  function onPointerMove(event) {
    const drag = dragRef.current;
    if (!drag) return;
    setRy(drag.ry + (event.clientX - drag.x) * 0.42);
    setRx(Math.max(-72, Math.min(72, drag.rx - (event.clientY - drag.y) * 0.32)));
  }

  function onPointerUp() {
    dragRef.current = null;
  }

  function onWheel(event) {
    setZoom((value) => Math.max(0.75, Math.min(1.6, value + (event.deltaY > 0 ? -0.06 : 0.06))));
  }

  const orientation = reversed ? 'reversed' : 'upright';
  const keywords = (card.keywords[orientation] || []).slice(0, 3);

  return h(
    'div',
    {
      ref: rootRef,
      className: 'dsh-tarot-viewer-layer' + (inline ? ' is-inline' : ''),
      onMouseDown: inline
        ? undefined
        : (event) => {
            if (event.target === event.currentTarget) onClose();
          }
    },
    h(
      'div',
      {
        className: 'dsh-tarot-viewer' + (inline ? ' dsh-tarot-preview-page' : ''),
        role: inline ? 'region' : 'dialog',
        'aria-modal': inline ? undefined : 'true',
        'aria-label': cardName(card, localeId)
      },
      h(
        'button',
        {
          type: 'button',
          className: 'dsh-tarot-viewer-close' + (inline ? ' dsh-tarot-preview-back' : ''),
          onClick: onClose,
          'aria-label': inline ? t('library.previewBack') : t('viewer.close')
        },
        inline ? '‹ ' + t('library.previewBack') : '×'
      ),
      h(
        'div',
        {
          className: 'dsh-tarot-viewer-stage',
          onPointerDown,
          onPointerMove,
          onPointerUp,
          onPointerCancel: onPointerUp,
          onWheel,
          onDoubleClick: reset
        },
        h(
          'div',
          {
            className: 'dsh-tarot-viewer-card',
            style: { transform: 'rotateX(' + rx + 'deg) rotateY(' + ry + 'deg) scale(' + zoom + ')' }
          },
          h('div', { className: 'dsh-tarot-face dsh-tarot-back dsh-tarot-viewer-side' }, h(CardBackArt)),
          h('div', { className: 'dsh-tarot-face dsh-tarot-front dsh-tarot-viewer-side' }, h(CardFace, { card, localeId }))
        )
      ),
      h(
        'div',
        { className: 'dsh-tarot-viewer-meta' },
        h('p', { className: 'dsh-tarot-viewer-position' }, tr(t, 'viewer.position', { index: index + 1, total })),
        h('h2', { className: 'dsh-tarot-viewer-name' }, cardName(card, localeId)),
        h('p', { className: 'dsh-tarot-viewer-type' }, cardTypeLabel(card, t)),
        h(
          'p',
          { className: 'dsh-tarot-viewer-hint' },
          inline ? t('library.previewHint') : t('viewer.hint')
        ),
        h(
          'div',
          { className: 'dsh-tarot-viewer-orient' },
          h('span', { className: 'dsh-tarot-badge' }, t(orientation === 'reversed' ? 'orientation.reversed' : 'orientation.upright')),
          h(
            'button',
            {
              type: 'button',
              className: 'dsh-tarot-ghost',
              onClick: () => setReversed((value) => !value)
            },
            t('viewer.flip')
          )
        ),
        h(
          'p',
          { className: 'dsh-tarot-viewer-text' },
          card.text[orientation] || ''
        ),
        h(
          'div',
          { className: 'dsh-tarot-keyword-row' },
          keywords.map((word, wordIndex) =>
            h('span', { key: word + wordIndex, className: 'dsh-tarot-kw is-accent' }, word)
          )
        ),
        h(
          'div',
          { className: 'dsh-tarot-viewer-actions' },
          h('button', { type: 'button', className: 'dsh-tarot-ghost', onClick: onPrev }, '‹ ' + t('viewer.prev')),
          h('button', { type: 'button', className: 'dsh-tarot-ghost', onClick: reset }, t('viewer.reset')),
          h(
            'button',
            {
              type: 'button',
              className: 'dsh-tarot-ghost' + (auto ? ' is-on' : ''),
              onClick: () => setAuto((value) => !value),
              'aria-pressed': auto
            },
            t('viewer.auto')
          ),
          h('button', { type: 'button', className: 'dsh-tarot-ghost', onClick: onNext }, t('viewer.next') + ' ›')
        )
      )
    )
  );
}

function LibraryScreen({ t, localeId }) {
  const [filter, setFilter] = React.useState('all');
  const [openId, setOpenId] = React.useState(null);
  const cards = CARDS.filter((card) => matchesLibraryFilter(card, filter));
  const index = cards.findIndex((card) => card.id === openId);
  const selected = index >= 0 ? cards[index] : null;

  function step(delta) {
    if (index < 0) return;
    const next = (index + delta + cards.length) % cards.length;
    setOpenId(cards[next].id);
  }

  if (selected) {
    return h(
      'section',
      { className: 'dsh-tarot-screen dsh-tarot-library dsh-tarot-library-preview' },
      h(CardViewer, {
        card: selected,
        t,
        localeId,
        index,
        total: cards.length,
        inline: true,
        onClose: () => setOpenId(null),
        onPrev: () => step(-1),
        onNext: () => step(1)
      })
    );
  }

  return h(
    'section',
    { className: 'dsh-tarot-screen dsh-tarot-library' },
    h('p', { className: 'dsh-tarot-kicker' }, t('library.kicker')),
    h('h1', { className: 'dsh-tarot-title' }, t('library.title')),
    h('p', { className: 'dsh-tarot-intro' }, t('library.intro')),
    h(
      'div',
      { className: 'dsh-tarot-lib-head' },
      h(
        'div',
        { className: 'dsh-tarot-lib-filters', role: 'group', 'aria-label': t('library.filters') },
        LIBRARY_FILTERS.map((entry) =>
          h(
            'button',
            {
              key: entry.id,
              type: 'button',
              className: 'dsh-tarot-lib-filter' + (filter === entry.id ? ' is-on' : ''),
              'aria-pressed': filter === entry.id,
              onClick: () => setFilter(entry.id)
            },
            t(entry.labelKey)
          )
        )
      ),
      h('span', { className: 'dsh-tarot-lib-count' }, tr(t, 'library.count', { count: cards.length }))
    ),
    h(
      'div',
      { className: 'dsh-tarot-lib-grid' },
      cards.map((card) => {
        const art = typeof CARD_ART === 'object' && CARD_ART ? CARD_ART[card.id] : '';
        return h(
          'button',
          {
            key: card.id,
            type: 'button',
            className: 'dsh-tarot-lib-card',
            onClick: () => setOpenId(card.id),
            'aria-label': cardName(card, localeId)
          },
          art
            ? h('img', { src: art, alt: '', loading: 'lazy', draggable: false, decoding: 'async' })
            : h('div', { className: 'dsh-tarot-lib-fallback' }, h(CardFace, { card, localeId })),
          h('span', { className: 'dsh-tarot-lib-name' }, cardName(card, localeId)),
          h('span', { className: 'dsh-tarot-lib-index' }, card.arcana === 'major' ? toRoman(card.number) : rankLabel(card.rank))
        );
      })
    )
  );
}

function FateScreen({ t, localeId, soundOn, onPotion, onShare }) {
  const [boot] = React.useState(() => {
    const storage = getStorage();
    return {
      draw: sanitizeFateDraw(loadFate(storage), DECK_BY_ID),
      ok: probeStorage(storage)
    };
  });
  const [fate, setFate] = React.useState(boot.draw);
  const [querent, setQuerent] = React.useState(boot.draw ? boot.draw.querent : '');
  const [view, setView] = React.useState(boot.draw ? 'result' : 'ask');
  const [storming, setStorming] = React.useState(false);
  const [revealed, setRevealed] = React.useState(!!boot.draw);
  const [flash, setFlash] = React.useState(false);
  const stageRef = React.useRef(null);
  const slotRef = React.useRef(null);
  const stopsRef = React.useRef([]);
  const resultTimer = React.useRef(0);
  const flashTimer = React.useRef(0);

  function stopAll() {
    stopsRef.current.forEach((stop) => {
      try {
        stop();
      } catch (error) {
        /* ignore */
      }
    });
    stopsRef.current = [];
  }

  React.useEffect(
    () => () => {
      stopAll();
      window.clearTimeout(resultTimer.current);
      window.clearTimeout(flashTimer.current);
    },
    []
  );

  React.useEffect(() => {
    if (soundOn) return;
    stopAll();
  }, [soundOn]);

  React.useEffect(() => {
    if (!storming) return undefined;
    const timer = window.setTimeout(() => finishFateStorm(true), STORM_MS + 800);
    return () => window.clearTimeout(timer);
  }, [storming]);

  const fateById = new Map(Object.keys(FATE).map((id) => [id, FATE[id]]));
  const reading = fate
    ? buildFateReading(fate, { deckById: DECK_BY_ID, fateById, t, locale: localeId })
    : null;

  function measureTargets() {
    const stage = stageRef.current;
    const element = slotRef.current;
    if (!stage || !element) return [];
    const stageRect = stage.getBoundingClientRect();
    const rect = element.getBoundingClientRect();
    return [
      {
        x: rect.left - stageRect.left,
        y: rect.top - stageRect.top,
        w: rect.width,
        h: rect.height
      }
    ];
  }

  function reveal(cardId) {
    setRevealed(true);
    setFlash(true);
    window.clearTimeout(flashTimer.current);
    flashTimer.current = window.setTimeout(() => setFlash(false), 780);
    if (soundOn) {
      stopAll();
      stopsRef.current = [playMajorSting(cardId)];
    }
    window.clearTimeout(resultTimer.current);
    resultTimer.current = window.setTimeout(() => setView('result'), 1150);
  }

  function beginFate(event) {
    if (event && typeof event.preventDefault === 'function') event.preventDefault();
    if (storming) return;
    const picked = drawFateCard(CARDS, fate);
    const next = makeFateDraw({
      cardId: picked.cardId,
      reversed: picked.reversed,
      querent
    });
    saveFate(getStorage(), next);
    setFate(next);
    setStorming(false);
    setRevealed(false);
    setFlash(false);
    setView('draw');
    stopAll();
    window.clearTimeout(resultTimer.current);
    if (soundOn) {
      stopsRef.current = [
        playWitchLaugh(),
        playCharge({ durationMs: STORM_MS, landingMs: SPIN_MS, count: 1 })
      ];
    }
    if (prefersReduced()) {
      setRevealed(true);
      if (soundOn) {
        window.setTimeout(() => {
          if (!stopsRef.current.length) return;
          stopAll();
          stopsRef.current = [playMajorSting(next.cardId)];
        }, 700);
      }
      resultTimer.current = window.setTimeout(() => setView('result'), 1400);
    } else {
      setStorming(true);
    }
  }

  function finishFateStorm(skipped) {
    if (skipped) stopAll();
    setStorming(false);
    if (fate) reveal(fate.cardId);
  }

  function goAsk() {
    stopAll();
    setStorming(false);
    setView('ask');
  }

  const ask = h(
    'section',
    { className: 'dsh-tarot-screen dsh-tarot-fate' },
    h('p', { className: 'dsh-tarot-kicker' }, t('fate.kicker')),
    h('h1', { className: 'dsh-tarot-title' }, t('fate.title')),
    h('p', { className: 'dsh-tarot-intro' }, t('fate.intro')),
    h(
      'form',
      { className: 'dsh-tarot-form dsh-tarot-fate-form', onSubmit: beginFate },
      h(
        'label',
        { className: 'dsh-tarot-field' },
        h('span', { className: 'dsh-tarot-field-label' }, t('fate.querentLabel')),
        h('input', {
          className: 'dsh-tarot-input',
          type: 'text',
          value: querent,
          maxLength: 24,
          placeholder: t('fate.querentPlaceholder'),
          onChange: (event) => setQuerent(event.target.value)
        })
      ),
      h(
        'div',
        { className: 'dsh-tarot-ask-actions' },
        h('button', { type: 'submit', className: 'dsh-tarot-primary big' }, t('fate.submit'))
      )
    )
  );

  const draw = h(
    'section',
    { className: 'dsh-tarot-screen dsh-tarot-fate' },
    h('p', { className: 'dsh-tarot-kicker' }, t('fate.drawKicker')),
    h('h1', { className: 'dsh-tarot-title' }, t('fate.drawTitle')),
    h(
      'div',
      { className: 'dsh-tarot-stage dsh-tarot-fate-stage', ref: stageRef },
      h(FateAltar),
      h(
        'div',
        { className: 'dsh-tarot-fate-slot', ref: slotRef },
        fate
          ? h(TarotCard, {
              card: DECK_BY_ID.get(fate.cardId),
              reversed: fate.reversed,
              revealed,
              scarlet: revealed,
              localeId,
              t
            })
          : h('div', { className: 'dsh-tarot-empty-card', 'aria-hidden': 'true' }, h('span', null, '✦'))
      ),
      storming
        ? h(CardStorm, { targets: measureTargets, onDone: finishFateStorm, t, count: 1, backArt: cardBackDataUrl })
        : null,
      flash ? h('span', { className: 'dsh-tarot-flash', 'aria-hidden': 'true' }) : null
    ),
    h('p', { className: 'dsh-tarot-draw-note' + (storming ? ' is-storm' : '') }, storming ? t('draw.flipHint') : t('fate.drawHint'))
  );

  const result = reading
    ? h(
        'section',
        { className: 'dsh-tarot-screen dsh-tarot-fate dsh-tarot-fate-result' },
        h('p', { className: 'dsh-tarot-kicker' }, t('fate.resultKicker')),
        h('h1', { className: 'dsh-tarot-title' }, t('fate.resultTitle')),
        h(
          'div',
          { className: 'dsh-tarot-fate-hero' },
          h(
            'div',
            { className: 'dsh-tarot-fate-card' },
            h(TarotCard, { card: reading.card, reversed: reading.reversed, revealed: true, scarlet: true, localeId, t })
          ),
          h(
            'div',
            { className: 'dsh-tarot-fate-copy' },
            h(
              'div',
              { className: 'dsh-tarot-fate-swatch-row' },
              h('span', { className: 'dsh-tarot-fate-swatch', style: { background: reading.color } }),
              h(
                'span',
                null,
                h('small', { className: 'dsh-tarot-fate-swatch-label' }, t('fate.color') + ' · ' + reading.colorName),
                h('strong', { className: 'dsh-tarot-fate-cardname' }, reading.name)
              )
            ),
            h('p', { className: 'dsh-tarot-fate-orient' }, reading.orientationLabel + (reading.reversed ? ' · ' + t('fate.shadowNote') : '')),
            h('p', { className: 'dsh-tarot-fate-essence' }, reading.essence),
            h(
              'div',
              { className: 'dsh-tarot-keyword-row' },
              reading.keywords.map((word, wordIndex) =>
                h('span', { key: word + wordIndex, className: 'dsh-tarot-kw is-accent' }, word)
              )
            ),
            h('p', { className: 'dsh-tarot-plain dsh-tarot-fate-text' }, reading.text),
            h(PotionButton, { reading, t, onClick: () => onPotion(reading) })
          )
        ),
        h(
          'div',
          { className: 'dsh-tarot-actions' },
          h(
            'button',
            { type: 'button', className: 'dsh-tarot-ghost', onClick: () => onShare(reading) },
            t('share.button')
          ),
          h('button', { type: 'button', className: 'dsh-tarot-primary', onClick: beginFate }, t('fate.again')),
          h('button', { type: 'button', className: 'dsh-tarot-ghost', onClick: goAsk }, t('fate.ask'))
        )
      )
    : null;

  return h(
    'div',
    null,
    !boot.ok ? h('p', { className: 'dsh-tarot-notice', role: 'status' }, t('storage.unavailable')) : null,
    view === 'ask' ? ask : null,
    view === 'draw' || (view === 'result' && storming) ? draw : null,
    view === 'result' && reading ? result : null
  );
}

