function OrbMotes() {
  return h(
    'div',
    { className: 'dsh-tarot-orb-motes', 'aria-hidden': 'true' },
    ORB_MOTES.map((mote, index) =>
      h(
        'span',
        {
          key: index,
          className:
            'dsh-tarot-mote is-' +
            mote.c +
            (mote.dot ? ' is-dot' : ''),
          style: {
            left: mote.x + '%',
            top: mote.y + '%',
            '--s': mote.s + 'px',
            '--dx': mote.dx + 'px',
            '--dy': mote.dy + 'px',
            '--dur': mote.d + 's',
            '--delay': mote.delay + 's'
          }
        },
        h('i', null)
      )
    )
  );
}

